function taskQuickActions(task){const outputs=state.outputs.filter(item=>item.taskId===task.id),output=outputs.find(item=>item.activePublished&&item.status==='published')||outputs.find(item=>item.status==='ready'&&item.attemptId);if(!output)return'';const kinds=new Set(Array.isArray(output.assetKinds)?output.assetKinds:[]),published=output.activePublished&&output.status==='published',items=[];if(published&&output.viewSessionUrl)items.push(button('view-output',output.id,'View',true));else if(output.status==='ready'&&output.attemptId&&can('viewer.processing.publish'))items.push(button('open-review',output.attemptId,'View',true));if(output.downloadProducts?.length||output.downloadUrl&&kinds.size)items.push(button('download-output',output.id,'Download',false,`data-url="${esc(output.downloadUrl)}"`));if(output.reportUrl&&kinds.has('report'))items.push(button('download-report',output.id,'Report',false,`data-url="${esc(output.reportUrl)}"`));if(canShareOutput(output))items.push(button('share-output',output.id,'Share'));return items.join('')}
function taskPanel(task){const attempt=task.latestAttempt||{},expanded=state.expandedTaskId===task.id,dataset=state.datasets.find(item=>item.id===task.datasetId),sourceImages=task.metrics?.sourceImageCount,panelId=`task-detail-${task.id}`,quickActions=taskQuickActions(task);return`<article class="task-panel ${expanded?'expanded':''}"><div class="task-summary"><button class="task-summary-toggle" data-action="toggle-task" data-id="${esc(task.id)}" aria-expanded="${expanded}" aria-controls="${esc(panelId)}"><span class="task-chevron" aria-hidden="true">›</span><span class="task-summary-name"><strong>${esc(task.displayName)}</strong><small>${dateTime(task.createdAt)}</small>${taskLodNotice(task)}</span><span class="task-summary-stat" title="${task.metrics?.sourceImageCountSource==='registered_camera_originals'?'Original photos registered with this model version; processing input count was not recorded.':'Registered source images; unavailable counts are not estimated.'}"><strong>${sourceImages??'Not recorded'}</strong><small>images</small></span><span class="task-summary-stat"><strong>${duration(attempt)}</strong><small>runtime</small></span>${badge(['ready_for_review','published'].includes(attempt.status||task.status)?'ready':attempt.status||task.status)}</button>${quickActions?`<div class="task-quick-actions row-actions" aria-label="${esc(task.displayName)} actions">${quickActions}</div>`:''}</div><div class="task-detail-shell" id="${esc(panelId)}" role="region" aria-label="${esc(task.displayName)} details" ${expanded?'':'inert'}><div class="task-detail-motion">${expanded?taskDetail(task,dataset):''}</div></div></article>`}
function taskFact(label,value){const display=label==='Reconstructed points'&&value!==null&&value!==undefined?groupedNumber(value):value;return`<div><dt>${esc(label)}</dt><dd>${available(display)}</dd></div>`}
function disclosureAttributes(taskId,name){return`data-task-id="${esc(taskId)}" data-task-disclosure="${esc(name)}" ${state.taskDisclosures[taskId]?.[name]?'open':''}`}
function taskDisclosurePanel(taskId,name,label,body,meta=''){return`<details class="task-subsection task-disclosure" ${disclosureAttributes(taskId,name)}><summary><span>${esc(label)}</span>${meta?`<small>${esc(meta)}</small>`:''}</summary><div class="task-disclosure-body">${body}</div></details>`}
function publishedOrthophoto(outputs){return outputs.find(output=>output.activePublished&&output.status==='published'&&Array.isArray(output.assetKinds)&&output.assetKinds.includes('ortho'))||null}
function orthophotoPreview(task,outputs){const output=publishedOrthophoto(outputs);if(!output)return'';const cached=state.orthophotoPreviews[output.id];if(cached?.status==='ready')return`<figure class="task-ortho-preview"><img src="${esc(cached.dataUrl)}" alt="Orthophoto preview for ${esc(task.displayName)}"><figcaption>Published orthophoto</figcaption></figure>`;if(cached?.status==='failed')return`<figure class="task-ortho-preview unavailable"><div role="img" aria-label="Orthophoto preview unavailable">Preview unavailable</div><figcaption>Published orthophoto</figcaption></figure>`;return`<figure class="task-ortho-preview loading"><canvas width="420" height="236" data-ortho-output-id="${esc(output.id)}" role="img" aria-label="Loading the published orthophoto preview for ${esc(task.displayName)}"></canvas><figcaption>Published orthophoto</figcaption></figure>`}
