async function importGcp(event){event.preventDefault();const form=event.currentTarget,file=form.elements.file.files[0];if(!file)return;const format=form.elements.format.value,contentText=await file.text(),previewPath=`/api/v1/datasets/${encodeURIComponent(form.dataset.datasetId)}/gcp-sets/import-preview`;let declarations,preview;try{preview=await api(previewPath,{method:'POST',body:{format,content:contentText}})}catch(error){if(format!=='emlid-all-columns-v1'||!error.message.includes('units are not explicit'))return toast(error.message,true);const input=await dialogs.form({title:'Declare GCP units',message:'This file does not declare projected units. Choose the units used by its survey coordinates.',submitLabel:'Continue',fields:[{name:'linearUnit',label:'Projected units',required:true,options:[{value:'',label:'Choose units…'},{value:'m',label:'Meters (m)'},{value:'ftUS',label:'US survey feet (ftUS)'}],value:''}]});if(!input)return;declarations={linearUnit:input.linearUnit};try{preview=await api(previewPath,{method:'POST',body:{format,content:contentText,declarations}})}catch(retryError){return toast(retryError.message,true)}}const body={displayName:form.elements.displayName.value,format,fileName:file.name,content:contentText,...(declarations?{declarations}:{})};openModal('Confirm GCP import',`<div class="gcp-preview"><p>The API parsed <strong>${preview.pointCount}</strong> points. Confirm this authoritative mapping before writing the set.</p><dl class="detail-list"><div><dt>Point identifier</dt><dd>${esc(preview.columns?.id||'Unavailable')}</dd></div><div><dt>Survey coordinates</dt><dd>${esc((preview.columns?.authoritative||[]).join(', ')||'Unavailable')}</dd></div><div><dt>Cross-check only</dt><dd>${esc((preview.columns?.crossCheck||[]).join(', ')||'Unavailable')}</dd></div><div><dt>Coordinate system</dt><dd>${esc(preview.provenance?.coordinateSystem||'Unavailable')}</dd></div><div><dt>Vertical datum</dt><dd>${esc(preview.provenance?.verticalDatum||'Unavailable')}</dd></div><div><dt>Linear unit</dt><dd>${esc(preview.provenance?.linearUnit||'Unavailable')}</dd></div></dl>${(preview.warnings||[]).map(warning=>`<p class="form-note">Warning: ${esc(warning)}</p>`).join('')}<div class="row-actions"><button class="secondary-button modal-cancel">Cancel</button><button class="primary-button gcp-confirm">Confirm import</button></div></div>`);modalContent.querySelector('.modal-cancel').onclick=()=>modal.close();modalContent.querySelector('.gcp-confirm').onclick=async()=>{modal.close();await mutate(`/api/v1/datasets/${encodeURIComponent(form.dataset.datasetId)}/gcp-sets/import`,{method:'POST',body:{...body,confirmationToken:preview.confirmationToken}},'GCP set imported');await refreshTaskDetails(form.dataset.taskId)}}

function associationModelId(item){return item?.modelId||item?.model_id||item?.viewerModelId||item?.viewer_model_id||null}
function associationProjectId(item){return item?.projectId||item?.project_id||null}
function portalAccountId(item){return item?.accountId||item?.account_id||null}
function exactClientAssociations(output,access=state.clientAccess){
  if(!output?.activePublished||output.status!=='published'||!output.modelId)return[];
  const projects=access?.projects||[],associations=access?.associations||[];
  return associations.filter(item=>{
    const project=projects.find(project=>project.id===associationProjectId(item));
    if(!item.id||associationModelId(item)!==output.modelId||!project||!portalAccountId(project))return false;
    if(portalAccountId(item)&&portalAccountId(item)!==portalAccountId(project))return false;
    return associations.filter(other=>associationModelId(other)===output.modelId
      &&associationProjectId(other)===project.id).length===1;
  });
}
function clientGrantBody(form,onlyOutputId){
  const projects=state.clientAccess?.projects||[];
  let project,association=null;
  if(onlyOutputId){
    const output=state.outputs.find(item=>item.id===onlyOutputId);
    association=exactClientAssociations(output).find(item=>item.id===form.elements.associationId.value);
    project=association&&projects.find(item=>item.id===associationProjectId(association));
    if(!association||!project)throw new Error('An exact Operations model association is required for this model.');
  }else{
    project=projects.find(item=>item.id===form.elements.projectId.value);
    if(!project||!portalAccountId(project)||!form.elements.wholeProject.checked)
      throw new Error('Select an Operations project and explicitly approve whole-project access.');
  }
  return{grant:{accountId:portalAccountId(project),projectId:project.id,scopeType:onlyOutputId?'task':'project',
    associationId:association?.id||null,includeFuturePublished:!onlyOutputId&&form.elements.includeFuturePublished.checked,
    expiresAt:form.elements.expiresAt.value?new Date(form.elements.expiresAt.value).toISOString():null,
    permissions:{measure:form.elements.measure.checked,cameras:form.elements.cameras.checked,download:form.elements.download.checked}}};
}
function clientShareCard(output,onlyOutputId){
  if(!can('viewer.client_grants.manage'))return card('Authenticated client access',empty('Client-access management requires an additional permission.'));
  const access=state.clientAccess;
  if(!access)return card('Authenticated client access',empty('Operations client access is unavailable. No access has been granted.'));
  const associations=onlyOutputId?exactClientAssociations(output):[],projects=access.projects||[];
  let form='';
  if(onlyOutputId&&(!output?.activePublished||output.status!=='published')){
    form=empty('Direct Operations client sharing is not available for this private ready model yet. Its verified activation and exact Operations association must be connected first; creating a public link is a separate choice, not a prerequisite for client access.');
  }else if(onlyOutputId&&!associations.length){
    form=empty('No unique Operations association matches this model. Set up its model association in Operations first. Other models and entire client projects will not be granted access here.');
  }else{
    const target=onlyOutputId
      ?`<label><span>Client Portal project for this exact model</span><select name="associationId" required><option value="">Select client project</option>${associations.map(item=>{const project=projects.find(project=>project.id===associationProjectId(item));return`<option value="${esc(item.id)}">${esc(project.clientName||project.client_name||'Client')} — ${esc(project.name||project.projectName||project.project_name||project.id)}</option>`}).join('')}</select></label><p class="form-note">Only this model. Future published tasks are not included.</p>`
      :`<label><span>Operations client project</span><select name="projectId" required><option value="">Select client project</option>${projects.filter(portalAccountId).map(project=>`<option value="${esc(project.id)}">${esc(project.clientName||project.client_name||'Client')} — ${esc(project.name||project.projectName||project.project_name||project.id)}</option>`).join('')}</select></label><label class="check"><input type="checkbox" name="wholeProject" required> Grant the entire selected Operations project, not just one Viewer model</label><label class="check"><input type="checkbox" name="includeFuturePublished"> Also include future published tasks</label>`;
    form=`<form id="client-grant-form" class="manage-form">${target}${field('Expiry (optional)','expiresAt','type="datetime-local"')}<label class="check"><input type="checkbox" name="measure" checked> Measurements</label><label class="check"><input type="checkbox" name="cameras" checked> Camera positions</label><label class="check"><input type="checkbox" name="download"> Downloads</label><button class="primary-button">Grant client access</button></form>`;
  }
  const ids=new Set(associations.map(item=>item.id)),grants=(access.grants||[]).filter(grant=>!onlyOutputId
    ||((grant.scopeType||grant.scope_type)==='task'&&ids.has(grant.associationId||grant.association_id)));
  return card('Authenticated client access',form+`<div class="data-list top-gap">${grants.map(grant=>`<div class="manage-row"><div><strong>${esc(grant.clientName||grant.client_name||grant.accountId)}</strong><small>${esc(grant.projectName||grant.project_name||grant.projectId)}</small></div>${badge(grant.status||'active')}<div>${(grant.status||'active')==='active'?button('revoke-client-grant',grant.id,'Revoke'):''}</div></div>`).join('')||empty('No matching authenticated client grants.')}</div>`);
}
function rememberShareResult(result,projectId,outputId){
  state.lastShareUrl=result.viewUrl;state.lastShareOutputId=outputId;
  state.lastShareResult={url:result.viewUrl,projectId,outputId,shareId:result.share.id,
    kind:outputId?'model':'project',expiresAt:result.share.expiresAt||null};
}
function clearShareResult(shareId,kind){
  if(state.lastShareResult?.shareId!==shareId||state.lastShareResult.kind!==kind)return;
  state.lastShareResult=null;state.lastShareUrl=null;state.lastShareOutputId=null;
}
function visibleShareResult(projectId,onlyOutputId){
  const result=state.lastShareResult;
  if(!result?.shareId||result.projectId!==projectId||result.url!==state.lastShareUrl
    ||(onlyOutputId&&result.outputId!==onlyOutputId))return null;
  const shares=result.kind==='project'?state.projectShares[result.projectId]:state.shares[result.outputId];
  const loaded=shares?.find(share=>share.id===result.shareId);
  const expiry=loaded?.expiresAt||result.expiresAt;
  if(loaded?.revokedAt||(expiry&&(!Number.isFinite(Date.parse(expiry))||Date.parse(expiry)<=Date.now()))){
    clearShareResult(result.shareId,result.kind);return null;
  }
  return result;
}
function shareModal(projectId,onlyOutputId=null){
  const project=state.projects.find(item=>item.id===projectId),taskIds=new Set(state.tasks.filter(task=>task.projectId===projectId).map(task=>task.id));
  const outputs=state.outputs.filter(output=>taskIds.has(output.taskId)&&(!onlyOutputId||output.id===onlyOutputId)
    &&(output.activePublished||output.status==='ready'));
  const selected=onlyOutputId?outputs.find(output=>output.id===onlyOutputId):null;
  const checking=state.shareContext?.loading===true;
  const result=visibleShareResult(projectId,onlyOutputId)
    ?card('New public link — copy now',`<div class="share-result"><input readonly aria-label="New public link" value="${esc(state.lastShareUrl)}"><button class="primary-button" data-action="copy-share" data-url="${esc(state.lastShareUrl)}">Copy</button></div><p class="form-note">Link created successfully. Anyone with this link can access the allowed model content.</p>`):'';
  const publicCards=outputs.map(output=>{
    const preflight=state.sharePreflight[output.id],ready=!output.activePublished;
    const mayCreate=can('viewer.shares.create')&&(!ready||can('viewer.processing.publish'));
    const blocked=Boolean(preflight?.error),warning=preflight?.existingAccessUpdateRequired
      ?'Activating this version can update existing model/client access and project links. Confirmation is required before creating the link.'
      :ready?'This model is private. Create public link activates its verified public derivatives and creates a revocable link.':'Links follow this model’s latest published version.';
    const form=checking?empty('Checking share eligibility…'):mayCreate&&!blocked
      ?`<form class="manage-form share-form" data-output-id="${esc(output.id)}">${field('Link label','label','maxlength="120"')}${field('Optional password','password','type="password" minlength="8" autocomplete="new-password"')}${field('Expiry (optional)','expiresAt','type="datetime-local"')}<label class="check"><input type="checkbox" name="measure" checked> Measurements</label><label class="check"><input type="checkbox" name="cameras" checked> Camera positions</label><label class="check"><input type="checkbox" name="download"> Downloads</label><p class="form-note">${esc(warning)}</p><button class="primary-button">Create public link</button></form>`
      :blocked?empty('Sharing eligibility could not be verified. Close and reopen Share to retry.'):empty('Creating a link requires share permission and, for private ready models, activation permission.');
    const list=can('viewer.shares.read')?`<div class="data-list top-gap">${(state.shares[output.id]||[]).map(share=>`<div class="manage-row"><div><strong>${esc(share.label||'Public link')}</strong><small>${share.hasPassword?'Password protected':'No password'}</small></div>${badge(share.revokedAt?'revoked':'active')}<div>${!share.revokedAt&&can('viewer.shares.revoke')?button('revoke-share',share.id,'Revoke'):''}</div></div>`).join('')||empty('No public links.')}</div>`:'';
    return card(output.displayName||'Model',form+list);
  }).join('')||card('Models',empty('No ready model is available to share.'));
  openModal(`Share ${selected?.displayName||project?.displayName||'model'}`,`<div class="share-columns" data-share-context="${esc(state.shareContext?.id||'')}"><div>${checking?card('Authenticated client access',empty('Checking client access…')):clientShareCard(selected,onlyOutputId)}</div><div>${result}${publicCards}</div></div>`,'wide-modal');
  bindShareModal(projectId,onlyOutputId);
}
async function confirmSharedVersionUpdate(){
  return dialogs.confirm('Activating this model version can change what existing model links, associated clients, and whole-project links can see. Whole-project links include newly activated tasks. Continue and create the public link?',
    {title:'Update existing shared access?',submitLabel:'Activate and create link'});
}
async function createOutputShare(form,projectId,onlyOutputId){
  if(form.shareBusy)return;
  form.shareBusy=true;
  const submit=form.querySelector('button[type="submit"],button:not([type])');
  if(submit)submit.disabled=true;
  try{
    const output=state.outputs.find(item=>item.id===form.dataset.outputId);
    if(!output||!can('viewer.shares.create')||(!output.activePublished&&!can('viewer.processing.publish')))throw new Error('Sharing is not permitted for this output.');
    const input=values(form);let body={label:input.label,expiresAt:input.expiresAt?new Date(input.expiresAt).toISOString():null,
      permissions:{view:true,measure:form.elements.measure.checked,cameras:form.elements.cameras.checked,download:form.elements.download.checked}};
    if(input.password)body.password=input.password;
    const inputSignature=JSON.stringify(body);
    if(form.shareRequest?.inputSignature===inputSignature)body={...form.shareRequest.body};
    else if(!output.activePublished){
      body.publishIfReady=true;
      if(state.sharePreflight[output.id]?.existingAccessUpdateRequired){
        if(!await confirmSharedVersionUpdate())return;
        body.allowExistingAccessUpdate=true;
      }
    }
    if(!modal.open||!form.isConnected)return;
    const send=()=>{
      const serialized=JSON.stringify(body);
      // Retain the key for the same payload after an uncertain network outcome.
      // A consent/body change is a new logical request with a new key.
      if(form.shareRequest?.serialized!==serialized)form.shareRequest={serialized,key:crypto.randomUUID(),body:{...body},inputSignature};
      return api(`/api/v1/processing/outputs/${encodeURIComponent(output.id)}/shares`,{
        method:'POST',body,headers:{'Idempotency-Key':form.shareRequest.key}});
    };
    let result;
    try{result=await send()}catch(error){
      if(error.status!==409||error.message!=='existing_access_update_confirmation_required'||body.allowExistingAccessUpdate)throw error;
      if(!await confirmSharedVersionUpdate()||!modal.open||!form.isConnected)return;
      body.allowExistingAccessUpdate=true;
      result=await send();
    }
    rememberShareResult(result,projectId,output.id);
    state.shares[output.id]=[result.share,...(state.shares[output.id]||[]).filter(share=>share.id!==result.share.id)];
    state.sharePreflight[output.id]={...state.sharePreflight[output.id],publicationRequired:false,existingAccessUpdateRequired:false,error:null};
    output.activePublished=true;output.status='published';
    delete form.shareRequest;
    toast('Public link created. Use Copy to share it.');
    // Clipboard is a separate explicit action, never part of creation success.
    if(modal.open&&form.isConnected){shareModal(projectId,onlyOutputId);if(!onlyOutputId)injectProjectShareCard(projectId)}
  }catch(error){toast(error.message,true)}
  finally{form.shareBusy=false;if(submit)submit.disabled=false}
}
function bindShareModal(projectId,onlyOutputId){
  const grantForm=modalContent.querySelector('#client-grant-form');
  if(grantForm)grantForm.onsubmit=async event=>{
    event.preventDefault();if(grantForm.shareBusy)return;grantForm.shareBusy=true;
    try{
      const body=clientGrantBody(grantForm,onlyOutputId);
      if(!onlyOutputId&&!await dialogs.confirm('Grant access to the entire selected Operations project? This is broader than one Viewer model.',
        {title:'Whole-project client access',submitLabel:'Grant project access'}))return;
      if(!modal.open||!grantForm.isConnected)return;
      const serialized=JSON.stringify(body);
      if(grantForm.shareRequest?.serialized!==serialized)grantForm.shareRequest={serialized,key:crypto.randomUUID()};
      const result=await api('/api/v1/workspace/client-grants',{method:'POST',body,headers:{'Idempotency-Key':grantForm.shareRequest.key}});
      state.clientAccess=result;toast('Client access granted');
      if(modal.open){shareModal(projectId,onlyOutputId);if(!onlyOutputId)injectProjectShareCard(projectId)}
    }catch(error){toast(error.message,true)}finally{grantForm.shareBusy=false}
  };
  modalContent.querySelectorAll('.share-form').forEach(form=>form.onsubmit=event=>{event.preventDefault();return createOutputShare(form,projectId,onlyOutputId)});
  modalContent.querySelectorAll('[data-action="revoke-client-grant"]').forEach(element=>element.onclick=async()=>{const input=await dialogs.form({title:'Revoke client access',submitLabel:'Revoke access',destructive:true,fields:[{name:'reason',label:'Reason for revoking this client access',required:true,maxLength:240}]});if(input){modal.close();mutate('/api/v1/workspace/client-grants',{method:'DELETE',body:{grantId:element.dataset.id,reason:input.reason}},'Client access revoked')}});
  modalContent.querySelectorAll('[data-action="revoke-share"]').forEach(element=>element.onclick=async()=>{
    if(!can('viewer.shares.revoke')||!await dialogs.confirm('Revoke this public link? Future access through this link will be blocked.',
      {title:'Revoke public link',submitLabel:'Revoke link',destructive:true}))return;
    modal.close();const revoked=await mutate(`/api/v1/processing/shares/${encodeURIComponent(element.dataset.id)}`,{method:'DELETE',body:{}},'Link revoked');
    if(revoked)clearShareResult(element.dataset.id,'model');
  });
  modalContent.querySelectorAll('[data-action="copy-share"]').forEach(element=>element.onclick=async()=>{
    try{if(!navigator.clipboard?.writeText)throw new Error('unavailable');await navigator.clipboard.writeText(element.dataset.url);toast('Link copied')}
    catch{toast('The link is created, but clipboard access is unavailable. Select the link above and copy it manually.',true)}
  });
}
